func TestRestoreLegitUnsettledTerminalsHaveNoSettlementInfo(t *testing.T) {
	t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)

	for _, cause := range []string{"payer", "revoke", "deactivate"} {
