// 携带实际费用或结算时间的备份同样整体拒绝，且与恢复时距离审批期限过去
// 多久无关。
func TestRestoreExpiredCarryingSettlementInfoRejected(t *testing.T) {
	t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
